import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { createStore } from 'vuex';

const initialState = {
  data: null,
  loading: false,
  error: null
};

const fetchDataAsync = createAsyncThunk(
  'data/fetchData',
  async () => {
    const response = await fetch('https://api.example.com/data');
    return response.json();
  }
);

const dataSlice = createSlice({
  name: 'data',
  initialState,
  reducers: {
    resetData: (state) => {
      state.data = null;
      state.loading = false;
      state.error = null;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchDataAsync.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchDataAsync.fulfilled, (state, action) => {
        state.loading = false;
        state.data = action.payload;
      })
      .addCase(fetchDataAsync.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message;
      });
  }
});

const store = createStore({
  modules: {
    data: dataSlice.reducer
  }
});

export default {
  name: 'DataComponent',
  computed: {
    data() {
      return this.$store.state.data.data;
    },
    loading() {
      return this.$store.state.data.loading;
    },
    error() {
      return this.$store.state.data.error;
    }
  },
  methods: {
    fetchData() {
      this.$store.dispatch('data/fetchData');
    },
    resetData() {
      this.$store.dispatch('data/resetData');
    }
  },
  template: `
    <div>
      <h1>Data Status</h1>
      <p v-if="loading">Loading...</p>
      <p v-else-if="error">Error: {{ error }}</p>
      <p v-else-if="data">Data: {{ data }}</p>
      <p v-else>No data loaded</p>
      <!-- Add buttons here -->
    </div>
  `
};
